import 'package:flutter/material.dart';import '../data/app_store.dart';import '../theme/operon_theme.dart';
class ProceduresScreen extends StatelessWidget{final AppStore store;const ProceduresScreen({super.key,required this.store});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Procedures')),body:ListView(children:[const Padding(padding:EdgeInsets.all(16),child:Text('Only approved/site-controlled procedures should be used for safety-critical work.',style:TextStyle(color:OperonTheme.muted))),...store.procedures.map((p)=>Card(margin:const EdgeInsets.symmetric(horizontal:16,vertical:6),child:ListTile(leading:const Icon(Icons.fact_check,color:OperonTheme.teal),title:Text(p.title),subtitle:Text('${p.category} · ${p.source}')))]));}
